N=22
out=[[5]*N for _ in range(N)]
objs=[(2,0,8,4),(8,0,8,3),(14,0,8,7),(16,5,8,9),(0,12,2,1),(2,17,2,3),(8,17,2,9),(14,17,2,7)] # top row, col, frame, fill
for r,c,frame,fill in objs:
    for i in range(5):
        for j in range(5):
            out[r+i][c+j]=fill if 1<=i<=3 and 1<=j<=3 else frame
print('\n'.join(' '.join(map(str,row)) for row in out))
